import "testing"

func TestPass(t *testing.T) {}

func TestFail(t *testing.T) {
	t.Log("before failure")
	t.Fatal("boom")
}

func TestSkip(t *testing.T) {
	t.Skip("later")
}

func TestParent(t *testing.T) {
	t.Run("ChildPass", func(t *testing.T) {})
	t.Run("ChildFail", func(t *testing.T) {
		t.Fatal("child boom")
	})
}

